static __attribute__((no_instrument_function)) enum print_line_t
trace_raw_output_irq_handler_entry(struct trace_iterator *iter, int flags,
				   struct trace_event *trace_event)
{
	struct trace_seq *s = &iter->seq;
	struct trace_seq __attribute__((__unused__)) *p = &iter->tmp_seq;
	struct trace_event_raw_irq_handler_entry *field;
	int ret;
	field = (typeof(field))iter->ent;
	ret = trace_raw_output_prep(iter, trace_event);
	if (ret != TRACE_TYPE_HANDLED)
		return ret;
	trace_event_printf(
		iter,
		"irq=%d name=%s"
		"\n",
		field->irq,
		((char *)((void *)field + (field->__data_loc_name & 0xffff))));
	return trace_handle_return(s);
}
